def seed():
    db = SessionLocal()
    try:
        total = 0
        for slug, questions in QUESTIONS.items():
            skill = db.query(Skill).filter(Skill.slug == slug).first()
            if not skill:
                print(f"  SKIP {slug} (not found)")
                continue
            for (text, difficulty, explanation, options) in questions:
                q = db.query(Question).filter(Question.text == text, Question.skill_id == skill.id).first()
                if not q:
                    q = Question(skill_id=skill.id, topic_id=None, text=text,
                                 difficulty=difficulty, explanation=explanation, is_active=True)
                    db.add(q)
                    db.flush()
                    for idx, (opt_text, is_correct) in enumerate(options):
                        db.add(QuestionOption(question_id=q.id, text=opt_text,
                                              is_correct=is_correct, order_index=idx))
                    total += 1
        db.commit()
        print(f"Done — {total} new questions inserted.")
    except Exception as e:
        db.rollback()
        raise
    finally:
        db.close()

if __name__ == "__main__":
    seed()
